(() => {
    'use strict';

    const host = document.querySelector('[data-home-live-map]');
    if (!host || !window.L) return;

    const canvas = host.querySelector('[data-home-map-canvas]');
    if (!canvas) return;

    const parse = value => {
        try { return JSON.parse(value || '[]'); } catch { return []; }
    };

    const DEFAULT_CENTER = [5.3484, -4.0305];
    const DEFAULT_ZOOM = 12.1;
    const isCoteIvoirePoint = point => {
        const lat = Number(point?.lat);
        const lng = Number(point?.lng);
        return Number.isFinite(lat) && Number.isFinite(lng) && lat >= 4.0 && lat <= 11.2 && lng >= -8.8 && lng <= -2.2;
    };
    const validPoint = point => Number.isFinite(Number(point?.lat)) && Number.isFinite(Number(point?.lng));
    const shops = parse(host.dataset.shops).filter(point => validPoint(point) && isCoteIvoirePoint(point));
    let drivers = parse(host.dataset.drivers).filter(point => validPoint(point) && isCoteIvoirePoint(point));
    const missions = parse(host.dataset.missions).filter(point => validPoint(point) && isCoteIvoirePoint(point));

    const configEl = document.getElementById('ops-map-config');
    let config = {};
    try { config = JSON.parse(configEl?.textContent || '{}'); } catch { config = {}; }

    const map = L.map(canvas, {
        zoomControl: false,
        scrollWheelZoom: false,
        zoomSnap: 0.1,
        minZoom: 8,
        attributionControl: true,
    }).setView(DEFAULT_CENTER, DEFAULT_ZOOM);

    const mapboxToken = String(config.token || '').trim();
    const tileUrl = mapboxToken
        ? `https://api.mapbox.com/styles/v1/mapbox/streets-v12/tiles/256/{z}/{x}/{y}@2x?access_token=${encodeURIComponent(mapboxToken)}`
        : 'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png';
    const attribution = mapboxToken
        ? '&copy; Mapbox &copy; OpenStreetMap'
        : '&copy; OpenStreetMap &copy; CARTO';

    const tileOptions = {
        maxZoom: 20,
        attribution,
    };
    if (!mapboxToken) tileOptions.subdomains = 'abcd';

    const baseLayer = L.tileLayer(tileUrl, tileOptions).addTo(map);
    baseLayer.on('tileerror', () => {
        host.classList.add('has-map-tile-error');
    });

    // Le cadrage initial est défini une seule fois lors de la création de la carte.
    // Ne jamais recentrer sur l'événement 'load' des tuiles : il se redéclenche
    // après chaque zoom et annulerait le zoom manuel de l'utilisateur.

    const shopLayer = L.layerGroup().addTo(map);
    const activityLayer = L.layerGroup().addTo(map);
    const driverLayer = L.layerGroup().addTo(map);
    const accuracyLayer = L.layerGroup().addTo(map);
    const routesLayer = L.layerGroup().addTo(map);
    const routes = parse(host.dataset.routes).filter(route => route && route.geometry && route.geometry.type === 'LineString');
    const markers = [];

    const node = (tag, className, text) => {
        const element = document.createElement(tag);
        if (className) element.className = className;
        if (text !== undefined && text !== null) element.textContent = String(text);
        return element;
    };

    const popupCard = ({eyebrow, title, lines = [], image, imageAlt = '', link, linkLabel = 'Ouvrir'}) => {
        const root = node('div', 'ops-home-map-popup');
        if (image) {
            const img = document.createElement('img');
            img.className = 'ops-home-map-popup-vehicle-photo';
            img.src = image;
            img.alt = imageAlt || title || 'Véhicule';
            img.loading = 'lazy';
            root.append(img);
        }
        if (eyebrow) root.append(node('span', 'ops-home-map-popup-eyebrow', eyebrow));
        root.append(node('strong', 'ops-home-map-popup-title', title));
        lines.filter(Boolean).forEach(line => root.append(node('span', 'ops-home-map-popup-line', line)));
        if (link) {
            const anchor = node('a', 'ops-home-map-popup-link', linkLabel);
            anchor.href = link;
            root.append(anchor);
        }
        return root;
    };

    const shopIcon = () => L.divIcon({
        className: '',
        iconSize: [28, 28],
        iconAnchor: [14, 14],
        html: '<span class="ops-home-shop-marker" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 9.5 5.5 4h13L21 9.5v2a3 3 0 0 1-3 3 3 3 0 0 1-3-3 3 3 0 0 1-6 0 3 3 0 0 1-6 0z"/><path d="M5 14v6h14v-6M9 20v-5h6v5"/></svg></span>',
    });

    const clusterIcon = count => L.divIcon({
        className: '',
        iconSize: [36, 36],
        iconAnchor: [18, 18],
        html: `<span class="ops-home-shop-cluster" aria-label="${count} boutiques">${count}</span>`,
    });

    const embeddedVehicleAssets = {
        'moto': "data:image/png;base64,",
        'tricycle': "data:image/png;base64,",
        'pickup': "data:image/png;base64,",
        'camion-3t': "data:image/png;base64,",
        'camion-10t': "data:image/png;base64,"
    };

    const vehicleAssetKey = driver => {
        const value = String(driver.vehicle_key || driver.vehicle || '').toLowerCase().replaceAll('-', '_').replaceAll(' ', '_');
        if (value.includes('tricycle') || value.includes('triporteur')) return 'tricycle';
        if (value.includes('moto') || value.includes('scooter')) return 'moto';
        if (value.includes('pickup') || value.includes('pick_up')) return 'pickup';
        if (value.includes('10t') || value.includes('10_t') || value.includes('truck10')) return 'camion-10t';
        if (value.includes('3t') || value.includes('3_t') || value.includes('truck3')) return 'camion-3t';
        return 'pickup';
    };

    const vehicleAssetUrl = driver => embeddedVehicleAssets[vehicleAssetKey(driver)] || embeddedVehicleAssets.pickup;


    const bearingBetween = (lat1, lng1, lat2, lng2) => {
        const toRad = deg => (deg * Math.PI) / 180;
        const dLng = toRad(lng2 - lng1);
        const y = Math.sin(dLng) * Math.cos(toRad(lat2));
        const x = Math.cos(toRad(lat1)) * Math.sin(toRad(lat2))
            - Math.sin(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.cos(dLng);
        return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360;
    };

    const driverIcon = driver => {
        const state = ['available', 'mission', 'unavailable'].includes(driver.status) ? driver.status : 'unavailable';
        const color = String(driver.vehicle_color_hex || '#6f7f8d').trim();
        const title = String(driver.name || '').replace(/"/g, '&quot;');
        const plate = String(driver.vehicle_plate || '').trim();
        const asset = vehicleAssetUrl(driver).replace(/"/g, '&quot;');
        // Sans rotation, l'icône garde toujours la même orientation quel que
        // soit le cap réel du véhicule (asset source pointant vers le nord).
        // Un cap à 0° sur téléphone immobile n'est pas une vraie donnée : on
        // s'oriente alors vers le prochain point du tracé de sa mission.
        let heading = Number(driver.heading);
        if (!Number.isFinite(heading) || Math.abs(heading) <= 0.05) {
            const route = routes.find(candidate => candidate?.geometry?.type === 'LineString');
            const coords = route?.geometry?.coordinates;
            if (coords && coords.length >= 2 && validPoint(driver)) {
                const lat = Number(driver.lat);
                const lng = Number(driver.lng);
                // Le tracé part de la boutique, pas du livreur : viser
                // directement son premier point pouvait orienter le véhicule
                // à l'envers. On cherche donc le point du tracé le plus
                // proche de sa position actuelle, puis on vise le suivant.
                let nearestIndex = 0;
                let nearestDistSq = Infinity;
                coords.forEach(([cLng, cLat], index) => {
                    const distSq = (cLat - lat) ** 2 + (cLng - lng) ** 2;
                    if (distSq < nearestDistSq) {
                        nearestDistSq = distSq;
                        nearestIndex = index;
                    }
                });
                // Le tracé vient maintenant de la même position live que
                // l'app livreur : il part toujours de sa position actuelle
                // vers sa cible du moment, donc toujours dans le sens
                // croissant de ses points (plus besoin de le lire à l'envers
                // avant collecte comme avec l'ancien tracé statique).
                const step = 1;
                let fromLat = lat;
                let fromLng = lng;
                let target = coords[nearestIndex + step];
                if (!target) {
                    const previous = coords[nearestIndex - step];
                    if (previous) {
                        target = coords[nearestIndex];
                        fromLat = previous[1];
                        fromLng = previous[0];
                    }
                }
                if (target) {
                    heading = bearingBetween(fromLat, fromLng, target[1], target[0]);
                }
            }
        }
        // L'asset est une illustration de profil (pas un pictogramme vu du
        // dessus) : la pivoter à un cap arbitraire la fait apparaître penchée
        // ou couchée. On se contente de la retourner à l'horizontale selon
        // que le véhicule va globalement vers l'est (image d'origine, qui
        // regarde vers la droite) ou vers l'ouest (miroir).
        const facingWest = Number.isFinite(heading) && Math.sin((heading * Math.PI) / 180) < 0;
        const shellStyle = facingWest ? ' style="transform:scaleX(-1)"' : '';

        return L.divIcon({
            className: '',
            iconSize: [78, 58],
            iconAnchor: [39, 29],
            html: `<span class="ops-home-driver-asset-marker is-${state}" title="${title}" style="--vehicle-color:${color};--vehicle-asset:url('${asset}')"><span class="ops-home-driver-asset-shell"${shellStyle}><img src="${asset}" alt="" loading="eager"></span>${plate ? `<b>${plate.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</b>` : ''}</span>`,
        });
    };

    const missionIcon = delayed => L.divIcon({
        className: '',
        iconSize: [30, 38],
        iconAnchor: [15, 34],
        html: `<span class="ops-home-mission-marker${delayed ? ' is-late' : ''}" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 22s7-5.2 7-12a7 7 0 1 0-14 0c0 6.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.6"/></svg></span>`,
    });

    const renderShops = () => {
        shopLayer.clearLayers();
        if (!shops.length) return;

        const zoom = map.getZoom();
        const cellSize = zoom >= 15 ? 1 : (zoom >= 13 ? 54 : 68);
        const groups = new Map();

        shops.forEach(shop => {
            if (cellSize === 1) {
                groups.set(`shop-${shop.id ?? shop.name}-${shop.lat}-${shop.lng}`, [shop]);
                return;
            }
            const point = map.project([Number(shop.lat), Number(shop.lng)], Math.round(zoom));
            const key = `${Math.floor(point.x / cellSize)}:${Math.floor(point.y / cellSize)}`;
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push(shop);
        });

        groups.forEach(group => {
            if (group.length === 1) {
                const shop = group[0];
                const marker = L.marker([Number(shop.lat), Number(shop.lng)], {icon: shopIcon(), keyboard: true})
                    .addTo(shopLayer)
                    .bindPopup(popupCard({
                        eyebrow: 'Boutique OVANIE',
                        title: shop.name || 'Boutique',
                        lines: [shop.commune, shop.address],
                    }), {maxWidth: 280});
                markers.push(marker);
                return;
            }

            const lat = group.reduce((sum, item) => sum + Number(item.lat), 0) / group.length;
            const lng = group.reduce((sum, item) => sum + Number(item.lng), 0) / group.length;
            const cluster = L.marker([lat, lng], {icon: clusterIcon(group.length), keyboard: true}).addTo(shopLayer);
            cluster.on('click', () => {
                const bounds = L.latLngBounds(group.map(item => [Number(item.lat), Number(item.lng)]));
                map.fitBounds(bounds, {padding: [55, 55], maxZoom: 16});
            });
            cluster.bindTooltip(`${group.length} boutiques OVANIE`, {direction: 'top', offset: [0, -15], className: 'ops-home-map-tooltip'});
        });
    };

    const renderDrivers = () => {
        driverLayer.clearLayers();
        accuracyLayer.clearLayers();
        drivers.forEach(driver => {
            const latLng = [Number(driver.lat), Number(driver.lng)];
            const accuracy = Number(driver.accuracy || 0);
            if (accuracy > 0 && accuracy <= 250) {
                L.circle(latLng, {
                    radius: accuracy,
                    color: driver.status === 'mission' ? '#2877dd' : driver.status === 'available' ? '#08a05c' : '#8694aa',
                    weight: 1,
                    fillOpacity: 0.07,
                    opacity: 0.22,
                    interactive: false,
                }).addTo(accuracyLayer);
            }
    
            const marker = L.marker(latLng, {icon: driverIcon(driver), zIndexOffset: 700, keyboard: true}).addTo(driverLayer);
            const seen = driver.recorded_at ? new Date(driver.recorded_at) : null;
            const seenLabel = seen && !Number.isNaN(seen.getTime())
                ? `GPS ${seen.toLocaleTimeString('fr-FR', {hour: '2-digit', minute: '2-digit'})}`
                : 'GPS récent';
            const extra = [];
            if (driver.vehicle_color) extra.push(`Couleur : ${driver.vehicle_color}`);
            if (driver.vehicle_plate) extra.push(`Immatriculation : ${driver.vehicle_plate}`);
            if (driver.zone) extra.push(`Zone : ${driver.zone}`);
            extra.push(seenLabel);
    
            marker.bindPopup(popupCard({
                eyebrow: driver.status_label || 'Livreur',
                title: driver.name || 'Livreur OVANIE',
                image: driver.vehicle_photo_url || vehicleAssetUrl(driver),
                imageAlt: `${driver.vehicle || 'Véhicule'} de ${driver.name || 'livreur'}`,
                lines: [driver.vehicle, ...extra],
                link: driver.tracking_url,
                linkLabel: 'Suivre le livreur',
            }), {maxWidth: 320});
            markers.push(marker);
        });
    };

    renderDrivers();

    // Le tracé de chaque mission active doit être visible dès l'accueil.
    routes.forEach(route => {
        L.geoJSON(route.geometry, {style: {color: '#ffffff', weight: 7, opacity: .95, lineCap: 'round'}}).addTo(routesLayer);
        L.geoJSON(route.geometry, {style: {color: '#1769e0', weight: 3.5, opacity: .95, lineCap: 'round'}}).addTo(routesLayer);
    });

    missions.forEach(mission => {
        const marker = L.marker([Number(mission.lat), Number(mission.lng)], {
            icon: missionIcon(Boolean(mission.delayed)),
            zIndexOffset: mission.delayed ? 650 : 500,
            keyboard: true,
        }).addTo(activityLayer);
        marker.bindPopup(popupCard({
            eyebrow: mission.delayed ? 'Mission en retard' : 'Mission active',
            title: mission.reference || 'Mission',
            lines: [mission.destination],
            link: mission.url,
            linkLabel: 'Voir la mission',
        }), {maxWidth: 290});
        markers.push(marker);
    });

    renderShops();
    map.on('zoomend', renderShops);

    const fit = () => {
        // Sur l'accueil, les opérations mobiles sont prioritaires. Les boutiques
        // ne doivent jamais forcer un dézoom à l'échelle du pays ou du monde.
        const operational = [...drivers, ...missions]
            .filter(point => validPoint(point) && isCoteIvoirePoint(point))
            .map(item => [Number(item.lat), Number(item.lng)]);

        if (operational.length) {
            const bounds = L.latLngBounds(operational);
            map.fitBounds(bounds, {paddingTopLeft: [58, 90], paddingBottomRight: [58, 70], maxZoom: 15});
            if (map.getZoom() < 10.5) map.setZoom(10.5);
            return;
        }

        const localShops = shops
            .filter(point => validPoint(point) && isCoteIvoirePoint(point))
            .map(item => [Number(item.lat), Number(item.lng)]);

        if (localShops.length) {
            const bounds = L.latLngBounds(localShops);
            // Si les données boutiques sont trop dispersées, garder une vue
            // opérationnelle d'Abidjan au lieu d'afficher toute la planète.
            const spanLat = Math.abs(bounds.getNorth() - bounds.getSouth());
            const spanLng = Math.abs(bounds.getEast() - bounds.getWest());
            if (spanLat <= 1.2 && spanLng <= 1.8) {
                map.fitBounds(bounds, {paddingTopLeft: [55, 80], paddingBottomRight: [55, 65], maxZoom: 14});
                if (map.getZoom() < 10.8) map.setZoom(10.8);
                return;
            }
        }

        map.setView(DEFAULT_CENTER, DEFAULT_ZOOM, {animate: false});
    };
    fit();

    host.querySelectorAll('[data-home-map-zoom]').forEach(button => {
        button.addEventListener('click', () => map.setZoom(map.getZoom() + Number(button.dataset.homeMapZoom || 0)));
    });
    host.querySelector('[data-home-map-center]')?.addEventListener('click', fit);
    host.querySelector('[data-home-map-fullscreen]')?.addEventListener('click', async () => {
        try {
            if (document.fullscreenElement) await document.exitFullscreen();
            else await host.requestFullscreen();
        } catch (_) {}
    });

    window.addEventListener('ovanie:dashboard-live', event => {
        const next = Array.isArray(event.detail?.map_drivers) ? event.detail.map_drivers : [];
        drivers = next.filter(point => validPoint(point) && isCoteIvoirePoint(point));
        renderDrivers();
    });

    document.addEventListener('fullscreenchange', () => setTimeout(() => map.invalidateSize(), 80));
    if (window.ResizeObserver) new ResizeObserver(() => map.invalidateSize()).observe(host);
})();
